def length(locations: List['Location'], _3d: bool) ->float:
    if not locations:
        return 0.0

    total_length = 0.0
    for i in range(len(locations) - 1):
        if _3d:
            dist = locations[i].distance_3d(locations[i + 1])
        else:
            dist = locations[i].distance_2d(locations[i + 1])

        if dist is not None:
            total_length += dist

    return total_length


def length_3d(locations: List['Location']) ->float:
    return length(locations, True)
